export const GROUPS = [{"id":"red","title":"What it lists in red"},{"id":"read","title":"How to read the trail"},{"id":"work","title":"How to work with it"},{"id":"settings","title":"Settings"}];
export const FEATURES = [{"group":"red","wcag":"2.1.1 A","title":"Missed spots","short":"\"2 look clickable, but Tab skips them.\" Red boxes mark them.","long":"A red box marks something that looks clickable, like a box with a pointer cursor, a button role or a click handler in the HTML. The keyboard never gets there."},{"group":"red","wcag":"2.1.1 A, 2.4.7 AA","title":"Hover menus","short":"\"1 menu or box opens only on mouse hover.\"","long":"A menu that opens on mouse hover but never when Tab reaches it hides its links from keyboard users. Tab trail reads the page's CSS and marks each one with a red box."},{"group":"red","wcag":"2.4.3 A","title":"Forced order","short":"\"1 stop has tabindex above 0, which pulls it ahead of the page.\"","long":"An element with tabindex=\"5\" gets Tab before the rest of the page, wherever it sits. When that changes the order, it is listed in red: set it to 0 and move the element in the HTML instead. If it was first anyway, the Log only notes it."},{"group":"red","wcag":"2.4.11 AA","title":"Hidden focus","short":"\"1 stop is hidden when Tab reaches it.\" Under a sticky bar.","long":"When Tab lands on something a sticky header, a cookie bar or a chat button covers completely, the panel lists it in red. Click it to scroll it into view. Fix it and Tab there again: it leaves the list. This check is new in WCAG 2.2 AA."},{"group":"red","wcag":"2.1.2 A","title":"Keyboard trap","short":"\"1 stop where Tab gets stuck.\"","long":"When Tab and Shift+Tab both leave focus on the same spot, a keyboard user can't get out. The panel lists that stop in red, once, like \"2: Message\". A spot that keeps Tab but says how to leave, like a code editor, is not red."},{"group":"red","wcag":"2.4.3 A","title":"Lost focus","short":"\"1 popup loses focus when it closes.\"","long":"When a popup or cookie bar closes, focus should go back to the button that opened it. If it drops to the top of the page instead, the panel lists it in red, like \"2 → Start\"."},{"group":"red","wcag":"2.4.3 A","title":"Out of order","short":"\"1 time Tab jumped out of order.\"","long":"Each time Tab jumps out of order, the panel lists the jump in red. A popup that blocks the page must get Tab first, or it is flagged too."},{"group":"read","title":"Tab order","short":"Numbers show where Tab goes. The orange one is where you are.","long":"Each dot is 1 press of the Tab key, in the order the keyboard visits, and the one you are on turns orange. A line that jumps all over the page will confuse people."},{"group":"read","title":"Hidden links","short":"Skip links show as dashed dots.","long":"Some links stay hidden until Tab reaches them, like \"Skip to content\". They get a dashed dot in the top left corner."},{"group":"read","title":"Inside dialogs","short":"A dialog opens? The trail goes in too.","long":"When a page opens a modal dialog (the HTML <dialog> element), the trail goes in too and shows only the stops there. Close it and the page comes back."},{"group":"read","title":"Late arrivals","short":"Scroll, and new buttons get counted.","long":"It checks again as you scroll. Buttons that only appear later, like a back to top arrow, get counted too."},{"group":"read","title":"Big pages","short":"Over 50 stops? See 50 at a time.","long":"Over 50 stops, it shows 50 at a time. Next and Previous page through them, and Tab turns the page for you. Untick Show 50 stops at a time to see them all."},{"group":"work","title":"Copy for AI","short":"Paste the problems into your AI. It gets the fix.","long":"Copies only the problems, each with its WCAG rule, a CSS selector, the HTML, the component and a fix hint. Paste it into your coding AI and it knows where to look."},{"group":"work","title":"Out of the way","short":"Drag the panel anywhere, or send it to a corner.","long":"Grab the panel and drag it anywhere, or press the corner button to move it to the next corner. It only moves by itself to stay on screen when it grows, and Compact view under Settings keeps it small."},{"group":"work","title":"Play it","short":"No Tab key? Press Play, it walks every stop.","long":"Play moves focus through every stop for you and checks each one, then 1 line sums up all 7 checks. It only moves focus, it never clicks."},{"group":"work","title":"The count","short":"Fix it, run it again, compare.","long":"The panel counts the stops and the spots Tab skips. Fix something, run it again and compare the numbers."},{"group":"work","title":"Find it","short":"Click a red spot in the list to see it.","long":"The panel lists every spot Tab never reaches, named by its label or text, 50 at a time. Click one and the page scrolls to it and outlines it."},{"group":"work","title":"Log","short":"See every check, the good ones too.","long":"Every check as it runs: OK, PROBLEM, SKIPPED with why, or INFO. Filter it, tick Show WCAG to see each rule, click a stop number to jump there, copy it for a bug report, or keep it live in a new tab."},{"group":"work","title":"Keyboard","short":"No mouse? Ctrl+Shift+F jumps into the panel.","long":"Press Ctrl+Shift+F, on a Mac and on Windows, and focus jumps to Play in the panel, where Tab reaches every button. Escape takes you back to the stop you were on."},{"group":"work","title":"Jump there","short":"Click a number and focus moves there.","long":"Click any number and focus moves to that spot, as if you had tabbed there. The next Tab goes on from it, and it is not counted as a jump."},{"group":"settings","title":"Spotlight","short":"Dim the page, light up where Tab is.","long":"Open Settings and tick Spotlight: the page goes dark except what Tab is on, so you follow it the way a keyboard user does. A missing focus ring is easy to spot, even for someone watching."},{"group":"settings","title":"Show lines","short":"Just the numbers? Untick Show lines.","long":"Open Settings and untick Show lines, and only the numbered dots stay. Long lines turns grey until you tick Show lines again."},{"group":"settings","title":"Long lines","short":"Too many lines? Untick Long lines.","long":"Open Settings, untick Long lines, and no line is over 100 px. A longer one becomes 2 arrows, 1 from each stop. A line off screen becomes 1 arrow pointing its way."},{"group":"settings","title":"Out of Tab","short":"The panel stays out of the trail.","long":"Leave this panel out of Tab is ticked at first, so Tab never runs into the panel. Untick it and Tab reaches the panel's buttons too. Ctrl+Shift+F gets you in either way."}];
export const KEYS = {"title":"Keys","items":["Tab, Shift+Tab: Move along the trail.","Click a number: Focus jumps there. Click empty space and no stop is lit, so the next Tab is not judged.","Space, Tab, Escape: Pause Play. A click on the page pauses it too.","Ctrl+Shift+F: Jumps into the panel, on a Mac and on Windows. Escape takes you back to the stop you were on.","Escape: Closes it once you click empty space on the page, so the page's own menus keep Escape. The close button or the bookmark again close it too."]};
export const READ = {"items":["A green 0 means that check found nothing. A red number means it found something, and the chips under it take you there.","In the Log, OK passed, PROBLEM needs a fix, SKIPPED was not judged and says why, and INFO is a note.","Out of order is judged only for the Tab presses you make. Press Tab to the end, then Shift+Tab back.","Hidden focus is judged once the page stops scrolling. Press Play to test every stop.","Lost focus is judged only for the popups you open and close.","Everything is tested at your window size. Try a narrow window too."]};
export const QUIET = {"title":"When it stays quiet on purpose","items":["Tab reaches 1 item of a tab list, menu, list box, radio group, grid, tree or toolbar: the arrow keys do the rest, so the other items are not red.","A stop only partly under a sticky bar passes AA 2.4.11. The Log adds that AAA 2.4.12 wants it fully visible.","Jumps into or inside a popup are fine, and small bars that leave the page usable are never flagged.","A popup closed by a click outside it is not judged for Lost focus.","On a Mac, a Tab press that skips only links (Firefox) or only links and buttons (Safari) is SKIPPED, not a jump, until you turn on Tab for them.","Tab moving inside a date field, a video or a frame is SKIPPED: those have parts of their own.","After a skip link moves focus to the main content, the next Tab is judged from there, not from the top."]};
export const API = [{"call":"await window.__tabTrail.play({ ignore, delay })","gives":"Walks every stop, or until it is paused, then gives back the report. Call it again to go on. ignore is a list of CSS selectors to leave out, like a part broken on purpose. delay is the wait at each stop, 400 ms if you leave it out. An ignore entry that isn't valid CSS makes it fail with an error."},{"call":"window.__tabTrail.problems()","gives":"Every open problem as data, never cut short: id (the same on every run), check, wcag, selector, html, component, fix, verify."},{"call":"window.__tabTrail.report()","gives":"The Copy for AI text."},{"call":"window.__tabTrail.log()","gives":"Every Log line as data: time, result, check, wcag, text, fixed, selector, stop."},{"call":"window.__tabTrail.state()","gives":"{ walked, total, done, untested }. done is true once Play reached the end. untested names the checks that never ran, like Lost focus when no popup was opened, so a green test can tell a clean page from a check that was skipped."},{"call":"window.__tabTrail.version","gives":"\"VERSION\""},{"call":"window.__tabTrail.close()","gives":"Closes it."}];
export const LIMITS = ["It spots clickable things by the pointer cursor, button roles and onclick in the HTML. A link with no address and no pointer cursor, or a click handler added only by script, stays hidden.","It checks that Tab gets there, not that Enter or Space then works.","A loop that Tab never leaves, but Shift+Tab does, shows as Out of order, not Keyboard trap.","It doesn't compare Tab order with the order you see. If CSS moves things around, follow the numbers and check it yourself.","Play moves focus in Tab order without pressing the key, so code that listens for the Tab key only runs when you press Tab.","It doesn't check the focus ring's look or contrast (it only flags links that stay invisible while they have focus), or what a screen reader says. Use Spotlight to look for yourself, and VoiceOver or NVDA to listen. Pages inside frames and web components with closed shadow roots are skipped.","Style sheets loaded from other sites without CORS can't be read, so hover menus styled there are not checked.","It's made for Chrome, Edge, Firefox and Safari on a desktop computer. On a Mac, turn on Tab for links first, and Firefox needs the console."];
export const VS = ["Accessibility Insights, ANDI, WAVE, taba11y, Polypane, Firefox's Show Tabbing Order and the paid axe DevTools keyboard test all number your Tab stops, and Insights and paid axe flag some Tab problems too. Chrome DevTools shows the order of the HTML, not the order Tab takes. Tab trail numbers them too, then checks the things below.","It reads your CSS for menus that open only for the mouse, tests every stop for focus hidden under a sticky bar, and catches focus lost when a popup closes.","It hands each problem to your AI with a selector and a fix hint, and gives your tests window.__tabTrail.","Use them together. Tab trail is the keyboard part."];
export const CHANGES = [{"v":"1.0.0","t":"First public release: every Tab stop in order, 7 checks in red with their WCAG rule, Play, Copy for AI and window.__tabTrail for tests."}];
